mapper.select:
SELECT COUNT(*)
FROM mg_course_student

    student_id = #{studentId} AND course_id = #{courseId}

SELECT cs.student_id, s.real_name as student_name, s.student_code as student_number, cs.course_id, c.course_name, cs.grade, cs.enrollment_date, cs.status, c.teacher_id, t.real_name as teacher_name, c.semester, cs.create_time, cs.update_time FROM mg_course_student cs LEFT JOIN mg_course c ON cs.course_id = c.id LEFT JOIN mg_student s ON cs.student_id = s.id LEFT JOIN mg_teacher t ON c.teacher_id = t.id
s.is_deleted = 0 AND c.is_deleted = 0 AND t.is_deleted = 0
AND cs.student_id = #{studentId}
AND cs.course_id = #{courseId}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'asc' : 'desc'}
ORDER BY cs.create_time DESC

SELECT cs.student_id, s.real_name as student_name, s.student_code as student_number, cs.course_id, c.course_name, cs.grade, cs.enrollment_date, cs.status, c.teacher_id, t.real_name as teacher_name, c.semester, cs.create_time, cs.update_time FROM mg_course_student cs LEFT JOIN mg_course c ON cs.course_id = c.id LEFT JOIN mg_student s ON cs.student_id = s.id LEFT JOIN mg_teacher t ON c.teacher_id = t.id
s.is_deleted = 0 AND c.is_deleted = 0 AND t.is_deleted = 0
AND cs.course_id = #{courseId}
AND cs.student_id = #{studentId}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'asc' : 'desc'}
ORDER BY cs.create_time DESC
